"""Frozen evaluation harness for distilled models.

DO NOT MODIFY THIS FILE DURING OPTIMIZATION.
This is the eval script — the source of truth for the AutoResearch loop.
"""

import json
import re
from dataclasses import dataclass, field
from pathlib import Path


@dataclass
class EvalResult:
    """Result from evaluating one test case."""
    test_id: str
    task_type: str
    precision: float
    recall: float
    f1: float
    json_valid: bool
    entry_count_match: bool


@dataclass
class EvalSummary:
    """Aggregate eval results."""
    task_type: str
    total_cases: int
    mean_f1: float
    mean_precision: float
    mean_recall: float
    json_validity_rate: float
    entry_count_accuracy: float
    results: list[EvalResult] = field(default_factory=list)


def normalize_text(text: str) -> set[str]:
    """Normalize text to a bag of words for comparison."""
    return set(re.sub(r'[^\w\s]', '', text.lower()).split())


def entry_f1(predicted_entries: list[dict], gold_entries: list[dict]) -> tuple[float, float, float]:
    """Compute F1 between predicted and gold knowledge entries.

    Matching: a predicted entry matches a gold entry if:
    1. type fields match exactly
    2. summary fields have bag-of-words overlap >= 0.5
    """
    if not gold_entries and not predicted_entries:
        return 1.0, 1.0, 1.0
    if not gold_entries:
        return 0.0, 0.0, 0.0
    if not predicted_entries:
        return 0.0, 0.0, 0.0

    matched_gold = set()
    tp = 0

    for pred in predicted_entries:
        pred_words = normalize_text(pred.get("summary", ""))
        pred_type = pred.get("type", "")

        best_overlap = 0.0
        best_idx = -1

        for i, gold in enumerate(gold_entries):
            if i in matched_gold:
                continue
            if gold.get("type", "") != pred_type:
                continue

            gold_words = normalize_text(gold.get("summary", ""))
            if not pred_words or not gold_words:
                continue

            overlap = len(pred_words & gold_words) / len(pred_words | gold_words)
            if overlap > best_overlap:
                best_overlap = overlap
                best_idx = i

        if best_overlap >= 0.5 and best_idx >= 0:
            tp += 1
            matched_gold.add(best_idx)

    precision = tp / len(predicted_entries) if predicted_entries else 0.0
    recall = tp / len(gold_entries) if gold_entries else 0.0
    f1 = 2 * precision * recall / (precision + recall) if (precision + recall) > 0 else 0.0

    return precision, recall, f1


def evaluate_extraction(
    test_cases: list[dict],
    model_outputs: list[str],
) -> EvalSummary:
    """Evaluate extraction model outputs against gold test cases.

    Each test case: {"id": str, "input": str, "expected": {"entries": [...]}}
    Each model_output: raw JSON string from the model
    """
    results = []

    for case, output in zip(test_cases, model_outputs):
        json_valid = True
        try:
            parsed = json.loads(output)
            predicted = parsed.get("entries", []) if isinstance(parsed, dict) else []
        except json.JSONDecodeError:
            json_valid = False
            predicted = []

        gold = case["expected"].get("entries", [])
        precision, recall, f1 = entry_f1(predicted, gold)

        results.append(EvalResult(
            test_id=case["id"],
            task_type="extraction",
            precision=precision,
            recall=recall,
            f1=f1,
            json_valid=json_valid,
            entry_count_match=abs(len(predicted) - len(gold)) <= 1,
        ))

    n = len(results) or 1
    return EvalSummary(
        task_type="extraction",
        total_cases=len(results),
        mean_f1=sum(r.f1 for r in results) / n,
        mean_precision=sum(r.precision for r in results) / n,
        mean_recall=sum(r.recall for r in results) / n,
        json_validity_rate=sum(1 for r in results if r.json_valid) / n,
        entry_count_accuracy=sum(1 for r in results if r.entry_count_match) / n,
        results=results,
    )


def load_test_cases(path: str | Path) -> list[dict]:
    """Load test cases from a JSONL file."""
    cases = []
    with open(path, encoding="utf-8") as f:
        for line in f:
            line = line.strip()
            if line:
                cases.append(json.loads(line))
    return cases
